def DualEventualBound (f : ℕ → (X →L[𝕜] 𝕜)) (r : ℝ) : Prop :=
  ∀ x : X, ∀ ε : ℝ, 0 < ε →
    ∀ᶠ n in atTop, ‖f n x‖ ≤ (r + ε) * ‖x‖

